protected override void OnModelCreating(ModelBuilder modelBuilder)
{
    modelBuilder.Entity<Product>(entity =>
    {
        entity.ToContainer("Products");

        // Preserve EF Core 8 discriminator property name so existing 500K documents
        // (which store "Discriminator": "Product") remain readable.
        // Without this, EF Core 9 defaults to "$type" and can't find old documents.
        entity.HasDiscriminator<string>("Discriminator");

        // Preserve EF Core 8 compound id format ("Product|123") so existing
        // documents remain accessible via FindAsync / point-reads.
        // Without this, EF Core 9 generates ids as just "123".
        entity.HasRootDiscriminatorInJsonId(true);
    });

    // REMOVED: HasIndex(p => p.Sku) — EF Core 9 Cosmos provider now throws on
    // HasIndex. Cosmos DB indexing is managed via the container's indexing policy
    // (Azure Portal / Bicep / Terraform), not through EF Core.
}

